"""Port of `src/lib/config.ts`.

Three things differ from the TS module on purpose:

  * `localstorage` mode is gone. MoonTV's `localstorage` branch built an
    `AdminConfig` in memory with no backing store; here there is always a real
    DB, so only the non-localstorage path is ported. Consequence: the
    `if (storageType === 'localstorage') return 400` gate in the admin/user
    routes is now reachable, and the client libs' `STORAGE_TYPE === 'localstorage'`
    branches are dead. Documented in PLAN.md, not faked.
  * `runtimeConfig` (the compile-time `src/lib/runtime.ts` generated by
    `scripts/generate-runtime.js`) has no Python equivalent — a Python process
    has no build step — so `config.json` is the only file-config source. It is
    resolved relative to this package, not `os.getcwd()`, so the app behaves the
    same whether uvicorn is started from the repo root or from `backend/`.
  * `refineConfig`, the `initConfig` adminConfig branch, and `getConfig` merge
    file sources slightly differently (existing entries keep `disabled` in two
    of them and lose it in the third; custom categories are only overwritten
    when `from === 'config'` in `getConfig`). The three bodies are kept
    separate rather than unified, so stored configs round-trip identically.
"""

from __future__ import annotations

import copy
import json
import os
import time

from .env import (
    ANNOUNCEMENT,
    DOUBAN_IMAGE_PROXY,
    DOUBAN_IMAGE_PROXY_TYPE,
    DOUBAN_PROXY,
    DOUBAN_PROXY_TYPE,
    DISABLE_YELLOW_FILTER,
    DANMU_API_BASE_URL,
    ENABLE_REGISTER,
    PASSWORD,
    PLAYBACK_SAVE_INTERVAL,
    SEARCH_MAX_PAGE,
    SITE_NAME,
    STORAGE_TYPE,
    USERNAME,
    env,
    env_bool,
    env_number,
)
from .playback_settings import get_default_playback_save_interval
from .storage.db import get_storage

ANNOUNCEMENT_DEFAULT = (
    "本网站仅提供影视信息搜索服务，所有内容均来自第三方网站。"
    "本站不存储任何视频资源，不对任何内容的准确性、合法性、完整性负责。"
)

API_CONFIG = {
    "search": {
        "path": "?ac=videolist&wd=",
        "pagePath": "?ac=videolist&wd={query}&pg={page}",
        "headers": {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
            "Accept": "application/json",
        },
    },
    "detail": {
        "path": "?ac=videolist&ids=",
        "headers": {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
            "Accept": "application/json",
        },
    },
}

# module state, mirroring `let fileConfig` / `let cachedConfig`
file_config: dict = {}
cached_config: dict | None = None

# `get_config` 每调用一次读一次 admin_config 表；热点路由（搜索/豆瓣/在线心跳）
# 高频调用，5s TTL 挡掉重复的 DB 读 + merge 开销。调用方无需改动，同形状返回。
# 返回的是深拷贝：路由拿到的是"像刚解析出来的 JSON"那样的独立对象（改
# `admin_config["UserConfig"]["Users"]` 不会污染缓存，失败路径也不会把没存进
# 库的改动泄漏给 5s 内的其他请求）——正是没有缓存之前每次读到的东西。
_CONFIG_TTL_S = 5.0
_CONFIG_CACHE: dict = {"data": None, "ts": 0.0}


def invalidate_config_cache() -> None:
    """写配置后调用，使下一次 `get_config` 重新读表。"""
    _CONFIG_CACHE["data"] = None
    _CONFIG_CACHE["ts"] = 0.0


def _config_file_path() -> str:
    override = os.environ.get("MOONTV_CONFIG_PATH")
    if override:
        return override
    return os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "config.json")


def _load_runtime_file_config() -> dict:
    """`DOCKER_ENV === 'true'` branch: read `config.json` from disk."""
    try:
        with open(_config_file_path(), encoding="utf-8") as handle:
            return json.load(handle)
    except Exception as error:  # noqa: BLE001 — mirrors the TS behaviour of leaving fileConfig stale
        print("load dynamic config failed:", error)
        return {}


def _parse_json_or_none(raw) -> dict | None:
    """`try { JSON.parse(x) } catch { null }`."""
    if not raw:
        return None
    try:
        return json.loads(raw)
    except Exception:  # noqa: BLE001
        return None


def _dump(obj) -> str:
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":"))


def _default_site_config(storage_type: str) -> dict:
    """The `SiteConfig` literal shared by `initConfig`/`resetConfig`."""
    return {
        "SiteName": env(SITE_NAME, "MoonTV"),
        "Announcement": env(ANNOUNCEMENT) or ANNOUNCEMENT_DEFAULT,
        "SearchDownstreamMaxPage": env_number(SEARCH_MAX_PAGE, 5),
        "SiteInterfaceCacheTime": (file_config or {}).get("cache_time") or 7200,
        "DoubanProxyType": env(DOUBAN_PROXY_TYPE, "direct"),
        "DoubanProxy": env(DOUBAN_PROXY, ""),
        "DoubanImageProxyType": env(DOUBAN_IMAGE_PROXY_TYPE, "direct"),
        "DoubanImageProxy": env(DOUBAN_IMAGE_PROXY, ""),
        "DisableYellowFilter": env_bool(DISABLE_YELLOW_FILTER),
        "DanmakuApiBaseUrl": env(DANMU_API_BASE_URL, ""),
        "TVBoxEnabled": False,
        "TVBoxPassword": "",
        "PlaybackSaveInterval": env_number(PLAYBACK_SAVE_INTERVAL)
        or get_default_playback_save_interval(storage_type),
    }


def refine_config(admin_config: dict) -> dict:
    """`refineConfig`."""
    global file_config
    file_config = _parse_json_or_none(admin_config.get("ConfigFile")) or {}

    api_site_entries = list(((file_config or {}).get("api_site") or {}).items())
    source_config_map: dict[str, dict] = {
        s["key"]: s for s in (admin_config.get("SourceConfig") or [])
    }

    for key, site in api_site_entries:
        existing = source_config_map.get(key)
        if existing:
            existing["name"] = site.get("name")
            existing["api"] = site.get("api")
            existing["detail"] = site.get("detail")
            existing["from"] = "config"
        else:
            source_config_map[key] = {
                "key": key,
                "name": site.get("name"),
                "api": site.get("api"),
                "detail": site.get("detail"),
                "from": "config",
                "disabled": False,
            }

    api_site_keys = {key for key, _ in api_site_entries}
    for source in source_config_map.values():
        if source["key"] not in api_site_keys:
            source["from"] = "custom"
    admin_config["SourceConfig"] = list(source_config_map.values())

    custom_categories = (file_config or {}).get("custom_category") or []
    custom_categories_map: dict[str, dict] = {
        (c.get("query") or "") + (c.get("type") or ""): c for c in (admin_config.get("CustomCategories") or [])
    }
    for category in custom_categories:
        key = (category.get("query") or "") + (category.get("type") or "")
        existed = custom_categories_map.get(key)
        if existed:
            existed["name"] = category.get("name")
            existed["query"] = category.get("query")
            existed["type"] = category.get("type")
            existed["from"] = "config"
        else:
            custom_categories_map[key] = {
                "name": category.get("name"),
                "type": category.get("type"),
                "query": category.get("query"),
                "from": "config",
                "disabled": False,
            }
    custom_category_keys = {(c.get("query") or "") + (c.get("type") or "") for c in custom_categories}
    for category in custom_categories_map.values():
        if (category.get("query") or "") + (category.get("type") or "") not in custom_category_keys:
            category["from"] = "custom"
    admin_config["CustomCategories"] = list(custom_categories_map.values())

    if (file_config or {}).get("cache_time") is not None:
        admin_config.setdefault("SiteConfig", {})["SiteInterfaceCacheTime"] = file_config["cache_time"]

    return admin_config


async def init_config() -> None:
    """`initConfig` — non-localstorage path."""
    global cached_config, file_config
    invalidate_config_cache()
    if cached_config:
        return

    file_config = _load_runtime_file_config()

    storage = get_storage()
    try:
        admin_config = await storage.get_admin_config() if hasattr(storage, "get_admin_config") else None

        user_names: list[str] = []
        if hasattr(storage, "get_all_users"):
            try:
                user_names = await storage.get_all_users()
            except Exception as error:  # noqa: BLE001
                print("获取用户列表失败:", error)

        if admin_config:
            parsed = _parse_json_or_none(admin_config.get("ConfigFile"))
            if parsed is None:
                print("解析配置文件失败:", "JSON parse error")
                file_config = {}
            else:
                file_config = parsed

            api_site_entries = list(((file_config or {}).get("api_site") or {}).items())
            custom_categories = (file_config or {}).get("custom_category") or []

            source_config_map = {s["key"]: s for s in (admin_config.get("SourceConfig") or [])}
            for key, site in api_site_entries:
                source_config_map[key] = {
                    "key": key,
                    "name": site.get("name"),
                    "api": site.get("api"),
                    "detail": site.get("detail"),
                    "from": "config",
                    "disabled": False,
                }
            admin_config["SourceConfig"] = list(source_config_map.values())

            api_site_keys = {key for key, _ in api_site_entries}
            for source in admin_config["SourceConfig"]:
                if source["key"] not in api_site_keys:
                    source["from"] = "custom"

            if not admin_config.get("CustomCategories"):
                admin_config["CustomCategories"] = []

            custom_map = {
                (c.get("query") or "") + (c.get("type") or ""): c for c in admin_config["CustomCategories"]
            }
            for category in custom_categories:
                custom_map[(category.get("query") or "") + (category.get("type") or "")] = {
                    "name": category.get("name"),
                    "type": category.get("type"),
                    "query": category.get("query"),
                    "from": "config",
                    "disabled": False,
                }
            custom_keys = {(c.get("query") or "") + (c.get("type") or "") for c in custom_categories}
            for category in custom_map.values():
                if (category.get("query") or "") + (category.get("type") or "") not in custom_keys:
                    category["from"] = "custom"
            admin_config["CustomCategories"] = list(custom_map.values())

            existed_users = {u.get("username") for u in (admin_config.get("UserConfig") or {}).get("Users") or []}
            user_config = admin_config.setdefault("UserConfig", {"AllowRegister": False, "Users": [], "Groups": []})
            for uname in user_names:
                if uname not in existed_users:
                    user_config["Users"].append({"username": uname, "role": "user"})

            owner_user = env(USERNAME)
            if owner_user:
                user_config["Users"] = [u for u in user_config["Users"] if u.get("username") != owner_user]
                user_config["Users"].insert(0, {"username": owner_user, "role": "owner"})

            if not admin_config.get("UserConfig"):
                admin_config["UserConfig"] = {"AllowRegister": False, "Users": [], "Groups": []}
            if not (admin_config["UserConfig"]).get("Groups"):
                admin_config["UserConfig"]["Groups"] = []
        else:
            file_config = _load_runtime_file_config()
            all_users = [{"username": uname, "role": "user"} for uname in user_names]
            owner_user = env(USERNAME)
            if owner_user:
                all_users = [u for u in all_users if u["username"] != owner_user]
                all_users.insert(0, {"username": owner_user, "role": "owner"})

            admin_config = {
                "ConfigFile": _dump(file_config),
                "SiteConfig": _default_site_config(env(STORAGE_TYPE, "sqlite")),
                "UserConfig": {
                    "AllowRegister": env_bool(ENABLE_REGISTER),
                    "Users": all_users,
                    "Groups": [],
                },
                "SourceConfig": [
                    {
                        "key": key,
                        "name": site.get("name"),
                        "api": site.get("api"),
                        "detail": site.get("detail"),
                        "from": "config",
                        "disabled": False,
                    }
                    for key, site in (file_config or {}).get("api_site", {}).items()
                ],
                "CustomCategories": [
                    {
                        "name": category.get("name"),
                        "type": category.get("type"),
                        "query": category.get("query"),
                        "from": "config",
                        "disabled": False,
                    }
                    for category in (file_config or {}).get("custom_category") or []
                ],
                "SubscriptionConfig": {},
            }

        if hasattr(storage, "set_admin_config"):
            await storage.set_admin_config(admin_config)
        cached_config = admin_config
    except Exception as error:  # noqa: BLE001
        print("加载管理员配置失败:", error)


async def get_config() -> dict:
    """`getConfig` — non-localstorage path."""
    global cached_config, file_config

    now = time.monotonic()
    if _CONFIG_CACHE["data"] is not None and now - _CONFIG_CACHE["ts"] < _CONFIG_TTL_S:
        return copy.deepcopy(_CONFIG_CACHE["data"])

    storage = get_storage()
    admin_config = await storage.get_admin_config() if hasattr(storage, "get_admin_config") else None

    if admin_config is None:
        await init_config()
        if cached_config is not None:
            _CONFIG_CACHE["data"] = cached_config
            _CONFIG_CACHE["ts"] = time.monotonic()
            return copy.deepcopy(cached_config)
        return cached_config

    if not admin_config.get("CustomCategories"):
        admin_config["CustomCategories"] = []

    site = admin_config.setdefault("SiteConfig", {})
    user_config = admin_config.setdefault("UserConfig", {})

    site["SiteName"] = site.get("SiteName") or env(SITE_NAME, "MoonTV")
    site["Announcement"] = site.get("Announcement") or env(ANNOUNCEMENT) or ANNOUNCEMENT_DEFAULT
    user_config["AllowRegister"] = (
        user_config["AllowRegister"] if isinstance(user_config.get("AllowRegister"), bool) else env_bool(ENABLE_REGISTER)
    )
    site["DoubanProxyType"] = site.get("DoubanProxyType") or env(DOUBAN_PROXY_TYPE, "direct")
    site["DoubanProxy"] = site.get("DoubanProxy") or env(DOUBAN_PROXY, "")
    site["DoubanImageProxyType"] = site.get("DoubanImageProxyType") or env(DOUBAN_IMAGE_PROXY_TYPE, "direct")
    site["DoubanImageProxy"] = site.get("DoubanImageProxy") or env(DOUBAN_IMAGE_PROXY, "")
    site["DisableYellowFilter"] = (
        site["DisableYellowFilter"] if isinstance(site.get("DisableYellowFilter"), bool) else env_bool(DISABLE_YELLOW_FILTER)
    )
    site["DanmakuApiBaseUrl"] = site.get("DanmakuApiBaseUrl") or env(DANMU_API_BASE_URL, "") or ""
    interval = site.get("PlaybackSaveInterval")
    site["PlaybackSaveInterval"] = (
        interval
        if isinstance(interval, (int, float)) and not isinstance(interval, bool) and interval > 0
        else env_number(PLAYBACK_SAVE_INTERVAL) or get_default_playback_save_interval(env(STORAGE_TYPE, "sqlite"))
    )
    site["TVBoxEnabled"] = site["TVBoxEnabled"] if isinstance(site.get("TVBoxEnabled"), bool) else False
    site["TVBoxPassword"] = site["TVBoxPassword"] if isinstance(site.get("TVBoxPassword"), str) else ""

    parsed = _parse_json_or_none(admin_config.get("ConfigFile"))
    if parsed is None:
        print("解析配置文件失败:", "JSON parse error")
        file_config = {}
    else:
        file_config = parsed

    api_site_entries = list(((file_config or {}).get("api_site") or {}).items())
    source_config_map = {s["key"]: s for s in (admin_config.get("SourceConfig") or [])}
    for key, site_entry in api_site_entries:
        existing = source_config_map.get(key)
        if existing:
            existing["name"] = site_entry.get("name")
            existing["api"] = site_entry.get("api")
            existing["detail"] = site_entry.get("detail")
            existing["from"] = "config"
        else:
            source_config_map[key] = {
                "key": key,
                "name": site_entry.get("name"),
                "api": site_entry.get("api"),
                "detail": site_entry.get("detail"),
                "from": "config",
                "disabled": False,
            }
    api_site_keys = {key for key, _ in api_site_entries}
    for source in source_config_map.values():
        if source["key"] not in api_site_keys:
            source["from"] = "custom"
    admin_config["SourceConfig"] = list(source_config_map.values())

    custom_categories = (file_config or {}).get("custom_category") or []
    custom_map = {
        (c.get("query") or "") + (c.get("type") or ""): c for c in (admin_config.get("CustomCategories") or [])
    }
    for category in custom_categories:
        key = (category.get("query") or "") + (category.get("type") or "")
        existing_category = custom_map.get(key)
        if existing_category:
            if existing_category.get("from") == "config":
                existing_category["name"] = category.get("name")
                existing_category["type"] = category.get("type")
                existing_category["query"] = category.get("query")
                existing_category["from"] = "config"
                existing_category["disabled"] = False
        else:
            custom_map[key] = {
                "name": category.get("name"),
                "type": category.get("type"),
                "query": category.get("query"),
                "from": "config",
                "disabled": False,
            }
    custom_category_keys = {(c.get("query") or "") + (c.get("type") or "") for c in custom_categories}
    for category in custom_map.values():
        if (category.get("query") or "") + (category.get("type") or "") not in custom_category_keys:
            category["from"] = "custom"
    admin_config["CustomCategories"] = list(custom_map.values())

    if (file_config or {}).get("cache_time") is not None:
        site["SiteInterfaceCacheTime"] = file_config["cache_time"]

    if admin_config.get("UserConfig") is None:
        admin_config["UserConfig"] = {"AllowRegister": False, "Users": [], "Groups": []}
    if "Groups" not in user_config or not user_config["Groups"]:
        user_config["Groups"] = []

    owner_user = env(USERNAME, "")
    contain_owner = False
    for user in user_config.get("Users") or []:
        if user.get("username") != owner_user and user.get("role") == "owner":
            user["role"] = "user"
        if user.get("username") == owner_user:
            contain_owner = True
            user["role"] = "owner"
    if not contain_owner:
        user_config.setdefault("Users", []).insert(0, {"username": owner_user, "role": "owner"})

    cached_config = admin_config
    _CONFIG_CACHE["data"] = admin_config
    _CONFIG_CACHE["ts"] = time.monotonic()
    return copy.deepcopy(admin_config)


def config_self_check(admin_config: dict) -> dict:
    """`configSelfCheck`."""
    if not admin_config.get("UserConfig"):
        admin_config["UserConfig"] = {"AllowRegister": False, "Users": []}
    if not isinstance(admin_config["UserConfig"].get("Users"), list):
        admin_config["UserConfig"]["Users"] = []
    if not isinstance(admin_config.get("SourceConfig"), list):
        admin_config["SourceConfig"] = []
    if not isinstance(admin_config.get("CustomCategories"), list):
        admin_config["CustomCategories"] = []
    if not admin_config.get("SubscriptionConfig"):
        admin_config["SubscriptionConfig"] = {}

    owner_user = env(USERNAME)
    original_owner = next((u for u in admin_config["UserConfig"]["Users"] if u.get("username") == owner_user), None)

    seen: set[str] = set()
    admin_config["UserConfig"]["Users"] = [
        user for user in admin_config["UserConfig"]["Users"] if user.get("username") not in seen and not seen.add(user.get("username"))
    ]
    admin_config["UserConfig"]["Users"] = [
        user for user in admin_config["UserConfig"]["Users"] if user.get("username") != owner_user
    ]
    for user in admin_config["UserConfig"]["Users"]:
        if user.get("role") == "owner":
            user["role"] = "user"

    owner_entry = {
        "username": owner_user,
        "role": "owner",
        "banned": (original_owner or {}).get("banned") or False,
        "group": (original_owner or {}).get("group"),
        "lastOnline": (original_owner or {}).get("lastOnline"),
    }
    # JSON.stringify drops undefined fields; do the same before storing.
    admin_config["UserConfig"]["Users"].insert(
        0, {k: v for k, v in owner_entry.items() if v is not None}
    )

    seen_keys: set[str] = set()
    admin_config["SourceConfig"] = [
        source for source in admin_config["SourceConfig"] if source.get("key") not in seen_keys and not seen_keys.add(source.get("key"))
    ]

    seen_category_keys: set[str] = set()
    admin_config["CustomCategories"] = [
        category
        for category in admin_config["CustomCategories"]
        if ((category.get("query") or "") + (category.get("type") or "")) not in seen_category_keys
        and not seen_category_keys.add((category.get("query") or "") + (category.get("type") or ""))
    ]

    return admin_config


async def reset_config() -> None:
    """`resetConfig` — the `/api/admin/reset` route's entry point."""
    global cached_config, file_config

    storage = get_storage()
    user_names: list[str] = []
    if hasattr(storage, "get_all_users"):
        try:
            user_names = await storage.get_all_users()
        except Exception as error:  # noqa: BLE001
            print("获取用户列表失败:", error)

    file_config = _load_runtime_file_config()
    api_site_entries = list((file_config or {}).get("api_site", {}).items())
    custom_categories = (file_config or {}).get("custom_category") or []

    storage_type = env(STORAGE_TYPE, "sqlite")
    all_users = [{"username": uname, "role": "user"} for uname in user_names]
    owner_user = env(USERNAME)
    if owner_user:
        all_users = [u for u in all_users if u["username"] != owner_user]
        all_users.insert(0, {"username": owner_user, "role": "owner"})

    admin_config = {
        "ConfigFile": _dump(file_config),
        "SiteConfig": _default_site_config(storage_type),
        "UserConfig": {"AllowRegister": env_bool(ENABLE_REGISTER), "Users": all_users},
        "SourceConfig": [
            {
                "key": key,
                "name": site.get("name"),
                "api": site.get("api"),
                "detail": site.get("detail"),
                "from": "config",
                "disabled": False,
            }
            for key, site in api_site_entries
        ],
        # `resetConfig` only rebuilds custom categories for redis; other backends
        # get an empty list. Kept, since it changes what a reset leaves behind.
        "CustomCategories": [
            {
                "name": category.get("name"),
                "type": category.get("type"),
                "query": category.get("query"),
                "from": "config",
                "disabled": False,
            }
            for category in custom_categories
        ]
        if storage_type == "redis"
        else [],
        "SubscriptionConfig": {},
    }

    if hasattr(storage, "set_admin_config"):
        await storage.set_admin_config(admin_config)

    if cached_config is None:
        cached_config = admin_config
    for field in ("ConfigFile", "SiteConfig", "UserConfig", "SourceConfig", "SubscriptionConfig"):
        cached_config[field] = admin_config[field]
    cached_config["CustomCategories"] = admin_config.get("CustomCategories") or []
    invalidate_config_cache()


async def get_cache_time() -> int:
    config = await get_config()
    return (config.get("SiteConfig") or {}).get("SiteInterfaceCacheTime") or 7200


async def get_available_api_sites(username: str | None = None) -> list[dict]:
    config = await get_config()
    all_sources = [s for s in (config.get("SourceConfig") or []) if not s.get("disabled")]

    def project():
        return [
            {
                "key": s.get("key"),
                "name": s.get("name"),
                "api": s.get("api"),
                "detail": s.get("detail"),
            }
            for s in all_sources
        ]

    groups = (config.get("UserConfig") or {}).get("Groups")
    if not username or not groups or len(groups) == 0:
        return project()

    user = next((u for u in (config["UserConfig"]).get("Users") or [] if u.get("username") == username), None)
    group_name = (user or {}).get("group")
    if not group_name:
        return project()
    group = next((g for g in groups if g.get("name") == group_name), None)
    if not group:
        return project()
    allowed = set(group.get("sourceKeys") or [])
    return [
        {"key": s.get("key"), "name": s.get("name"), "api": s.get("api"), "detail": s.get("detail")}
        for s in all_sources
        if s.get("key") in allowed
    ]


async def set_cached_config(config: dict) -> None:
    global cached_config
    cached_config = config
    invalidate_config_cache()
